const IndividualApplicationsUpgradeSchema = z.object({ "customer_id": z.string().describe("Customer ID returned at create time"), "idempotency_key": z.string().optional() }).strict().describe("Upgrade Account Tier\n\nTrigger Tier3 / EDD evaluation for an individual application.\n\nThis endpoint accepts no request body. Before calling it, provide the required `due_diligence` fields with `PATCH /applications/{customer_id}` and upload `POA` with `PUT /applications/{customer_id}/documents`.\n\nAllowed for the proactive Tier3 path (`kyc_status=APPROVED`, `edd_status=NOT_REQUIRED` or `REQUIRED`) and for KYC2-high recovery (`kyc_status=ACTION_REQUIRED`, `edd_status=REQUIRED`). The call returns `202 Accepted`, moves `edd_status` to `PENDING`, emits `kyc.upgrade_started`, and starts EDD evaluation.\n\nThe optional `Idempotency-Key` is webhook-correlation only. See the [Individual Onboarding Overview](https://developer.1money.com/reference/individual_onboarding_overview) for prerequisites, POA freshness, and EDD outcome webhooks.")
toolSchemas["individual_applications.upgrade"] = IndividualApplicationsUpgradeSchema;

const IndividualAccountsGetSchema = z.object({ "customer_id": z.string().describe("Customer ID") }).strict().describe("Get Individual Account\n\nRetrieve detailed information about an individual account.\n\n## Prerequisites\n\nThe account must be in APPROVED status (KYC completed and approved). The `customer_id` (Customer ID) is returned during onboarding — once an application is approved, it becomes the account.\n\n## Response Fields\n\n| Field | Description |\n|---|---|\n| `customer_id` | Customer ID from onboarding |\n| `email` | Account holder's email |\n| `first_name` | Account holder's first name |\n| `last_name` | Account holder's last name |\n| `person` | Submitted personal information |\n| `phone` | Submitted phone number |\n| `address` | Submitted residential address |\n| `identity` | Submitted identity information |\n| `document` | Submitted identity document data |\n| `due_diligence` | Submitted EDD data |\n| `status` | Account status (`ACTIVE`, `SUSPENDED`, `CLOSED`) |\n| `kyc_level` | `2` = Advanced KYC, `3` = EDD approved |\n| `approved_at` | When the account was approved (RFC 3339) |\n| `created_at` | When the application was created (RFC 3339) |")
toolSchemas["individual_accounts.get"] = IndividualAccountsGetSchema;

const IndividualAccountsGetLimitsSchema = z.object({ "customer_id": z.string().describe("Customer ID") }).strict().describe("Get Transaction Limits\n\nRetrieve withdrawal limits for an individual account based on the current KYC level.\n\n## Prerequisites\n\nThe account must be in APPROVED status.\n\n## Limits by KYC Level\n\n| KYC Level | Meaning | Limits |\n|---|---|---|\n| `1` | Basic KYC approved (US only) | Base daily + 30-day rolling limits |\n| `2` | Advanced KYC approved | Standard daily + 30-day rolling limits |\n| `3` | EDD approved | Highest daily + 30-day rolling limits |\n\n## Response Fields\n\n| Field | Description |\n|---|---|\n| `daily_withdrawal` | Maximum total withdrawal per calendar day (resets at UTC midnight) |\n| `daily_withdrawal_used` | USD amount already withdrawn today (rounded to 2 dp) |\n| `rolling_30d_withdrawal` | Maximum total withdrawal within a rolling 30-day sliding window |\n| `rolling_30d_withdrawal_used` | USD amount already withdrawn in the past 30 days (rounded to 2 dp) |\n| `currency` | Currency code for the limit amounts (e.g., `USD`) |")
toolSchemas["individual_accounts.get_limits"] = IndividualAccountsGetLimitsSchema;

const IndividualTosSessionsCreateSchema = z.object({ "request": z.object({ "redirect_url": z.string().describe("URL where the user will be redirected after signing the TOS agreement.\n\nAfter the user signs the agreement on the hosted page, they are redirected to this URL\nwith `?signed_agreement_id={id}` appended as a query parameter.\nUse this `signed_agreement_id` to create the application.") }).strict().describe("Request for creating a TOS signing session.") }).strict().describe("Create Individual Terms of Service URL\n\nCreates a hosted Terms of Service signing session for individual onboarding.\n\nRedirect the end user to the returned URL. After signing, the user is redirected to your `redirect_url` with a `signed_agreement_id`; send that value as `terms.signed_agreement_id` when creating the application.\n\nThe session expires in **1 hour**. See the [Individual Onboarding Overview](https://developer.1money.com/reference/individual_onboarding_overview) for the full TOS and application flow.")
toolSchemas["individual_tos_sessions.create"] = IndividualTosSessionsCreateSchema;

const IndividualTosSessionsSignSchema = z.object({ "session_token": z.string().describe("Session token from Create TOS Session response") }).strict().describe("Simulate Terms of Service Acceptance\n\nProgrammatically signs an individual onboarding TOS session.\n\n> **Sandbox/Testing Only**: In production, users must sign the TOS by visiting the URL returned from Create TOS Session.\n\nReturns a `signed_agreement_id` to send as `terms.signed_agreement_id` on `POST /v1/individuals/applications`.")
toolSchemas["individual_tos_sessions.sign"] = IndividualTosSessionsSignSchema;

const InstructionsGetDepositInstructionSchema = z.object({ "customer_id": z.string().describe("Customer ID"), "params": z.object({ "asset": z.string().describe("- Stablecoin assets: USDC, USDT, PYUSD, RLUSD, USDG, USDP, EURC, MXNB, 1USD(1USD/USDC conversion only, deposit/withdrawal not supported)\n- Digital assets: BTC\n- Fiat currencies: USD\n"), "network": z.string().describe("Deposit network. Crypto: ETHEREUM, POLYGON, ARBITRUM, AVALANCHE, BASE, BNBCHAIN, SOLANA, TRON, BITCOIN. Fiat: US_FEDWIRE, SWIFT.") }).strict() }).strict().describe("Get Deposit Instructions\n\nReturns the default deposit instruction for a specified asset and network.\n\n**Supported Instruction Types:**\n- **Fiat** — Bank account details for Wire and SWIFT deposits\n- **Crypto** — Wallet address for token deposits\n\n**Default Wallet Addresses:**\n\nEach customer is automatically assigned a default deposit address for the following networks:\n\n| Network | Type |\n|---|---|\n| EVM (e.g. Ethereum, Polygon, BNB Chain) | Default wallet address |\n| Solana | Default wallet address |\n| Tron | Default wallet address |\n| Bitcoin | Default wallet address |\n\nCustomers may also request additional deposit addresses on any of these networks. This endpoint always returns the default address only. To manage multiple addresses, use the following endpoints instead:\n\n| Endpoint | Description |\n|---|---|\n| `GET /all_deposit_instructions` | List all deposit addresses across all networks |\n| `POST /deposit_instruction` | Request an additional deposit address |\n| `GET /deposit_instruction/{id}` | Retrieve a specific deposit address by ID |\n\n> ⚠️ For crypto deposits, verify the token contract address carefully before transferring funds to ensure you are depositing the correct token.")
toolSchemas["instructions.get_deposit_instruction"] = InstructionsGetDepositInstructionSchema;

const InstructionsCryptoGetByIdempotencyKeySchema = z.object({ "customer_id": z.string().describe("Customer ID (UUID format)"), "idempotency_key": z.string().describe("HTTP `Idempotency-Key` header value. Stricter than other IDs:\n≤64 ASCII chars per the common REST API convention.") }).strict().describe("Get Crypto Deposit Address by Idempotency Key\n\nLook up a crypto deposit instruction using the idempotency key provided during creation.\n\n**Use Case:** Verify if a crypto deposit instruction was successfully created when network issues or timeouts occurred during the create request.\n\nFor EVM wallets, the `network` field indicates whether it was created as a specific chain (e.g., `ETHEREUM`) or as the virtual `EVM` network.")
toolSchemas["instructions.crypto.get_by_idempotency_key"] = InstructionsCryptoGetByIdempotencyKeySchema;

const InstructionsCryptoCreateSchema = z.object({ "customer_id": z.string().describe("Customer ID (UUID format)"), "request": z.object({ "network": z.string().describe("Blockchain network for the deposit address."), "nickname": z.union([z.string().describe("Optional nickname for the deposit address"), z.null().describe("Optional nickname for the deposit address")]).describe("Optional nickname for the deposit address").optional(), "idempotency_key": z.string() }).strict() }).strict().describe("Create Crypto Deposit Address\n\nCreate a new crypto deposit wallet address for a customer on a specific blockchain network.\n\n**Supported networks:** `EVM`, `ETHEREUM`, `POLYGON`, `BNBCHAIN`, `AVALANCHE`, `BASE`, `ARBITRUM`, `SOLANA`, `TRON`, `BITCOIN`.\n\n**EVM Network:** The `EVM` network is a virtual network representing all EVM-compatible chains. A single EVM deposit address can receive deposits from: Ethereum, Polygon, BNB Chain, Avalanche, Base, and Arbitrum.\n\n**Idempotency:** The `Idempotency-Key` header is required and must be a valid UUID. If a deposit instruction with the same key already exists and the parameters match, it will be returned. If the same key is used with different network or nickname, a 409 Conflict error is returned.")
toolSchemas["instructions.crypto.create"] = InstructionsCryptoCreateSchema;

const InstructionsCryptoListSchema = z.object({ "customer_id": z.string().describe("Customer ID (UUID format)"), "params": z.object({ "page": z.number().int().gte(1).describe("Page number (starts from 1, default: 1)").optional(), "size": z.number().int().gte(1).lte(100).describe("Number of items per page (1-100, default: 10)").optional() }).strict().optional() }).strict().describe("List Crypto Deposit Addresses\n\nList all  crypto deposit instructions for a customer with pagination.\n\n**EVM Network:** The `EVM` network is a virtual network representing all EVM-compatible chains. A single EVM deposit address can receive deposits from any of the following chains: `Ethereum`, `Polygon`, `BNB Chain`, `Avalanche`, `Base`, and `Arbitrum`. In the response, default EVM wallets are displayed with `network: \"EVM\"`.\n\n**Pagination:** Use `page` (1-based) and `size` (1-100, default 10) query parameters.")
toolSchemas["instructions.crypto.list"] = InstructionsCryptoListSchema;

const InstructionsCryptoGetSchema = z.object({ "customer_id": z.string().describe("Customer ID (UUID format)"), "deposit_instruction_id": z.string().describe("Deposit Instruction ID (wallet ID)") }).strict().describe("Get Crypto Deposit Address\n\nRetrieve a specific crypto deposit instruction by its ID.\n\nFor EVM wallets, the `network` field indicates whether it was created as a specific chain (e.g., `ETHEREUM`) or as the virtual `EVM` network. Default EVM wallets are displayed as `network: \"EVM\"`.")
toolSchemas["instructions.crypto.get"] = InstructionsCryptoGetSchema;

const AutoConversionRulesGetByIdempotencyKeySchema = z.object({ "customer_id": z.string().describe("Customer ID (UUID format)"), "idempotency_key": z.string().describe("HTTP `Idempotency-Key` header value. Stricter than other IDs:\n≤64 ASCII chars per the common REST API convention.") }).strict().describe("Get Auto-Conversion Rule by Idempotency Key\n\nLook up an Auto-Conversion Rule using the idempotency key provided during creation.\n\n**Use Case:** Verify if an Auto-Conversion Rule was successfully created when network issues or timeouts occurred during the create request.\n\n**Status & Deposit Info:**\n- `PENDING`: Deposit info is being prepared. `source_deposit_info` will be `null`.\n- `ACTIVE`: Deposit info is ready. `source_deposit_info` contains bank Wire/SWIFT details for fiat source, or wallet address for crypto source.")
