const AutoConversionRulesCreateSchema = z.object({ "customer_id": z.string().describe("Customer ID (UUID format)"), "request": z.object({ "source": z.object({ "asset": z.string().describe("- Stablecoin assets: USDC, USDT, PYUSD, RLUSD, USDG, USDP, EURC, MXNB, 1USD(1USD/USDC conversion only, deposit/withdrawal not supported)\n- Digital assets: BTC\n- Fiat currencies: USD\n"), "network": z.string() }).describe("Source asset and network configuration.\n- For fiat source (deposit): use fiat network (US_FEDWIRE, SWIFT)\n- For crypto source: use crypto network (ETHEREUM, POLYGON, etc.)"), "destination": z.object({ "asset": z.string().describe("- Stablecoin assets: USDC, USDT, PYUSD, RLUSD, USDG, USDP, EURC, MXNB, 1USD(1USD/USDC conversion only, deposit/withdrawal not supported)\n- Digital assets: BTC\n- Fiat currencies: USD\n"), "network": z.any().superRefine((x, ctx) => {
    const schemas = [z.null(), z.string()];
    const { errors, failed } = schemas.reduce<{
      errors: z.core.$ZodIssue[];
      failed: number;
    }>(
      ({ errors, failed }, schema) =>
        ((result) =>
          result.error
            ? {
                errors: [...errors, ...result.error.issues],
                failed: failed + 1,
              }
            : { errors, failed })(
          schema.safeParse(x),
        ),
      { errors: [], failed: 0 },
    );
    const passed = schemas.length - failed;
    if (passed !== 1) {
      ctx.addIssue(errors.length ? {
        path: [],
        code: "invalid_union",
        errors: [errors],
        message: "Invalid input: Should pass single schema. Passed " + passed,
      } : {
        path: [],
        code: "custom",
        errors: [errors],
        message: "Invalid input: Should pass single schema. Passed " + passed,
      });
    }
  }).optional(), "wallet_address": z.union([z.string().describe("Wallet address for automatic crypto withdrawal (fiat->crypto or crypto->crypto).\nOmit for conversion-only."), z.null().describe("Wallet address for automatic crypto withdrawal (fiat->crypto or crypto->crypto).\nOmit for conversion-only.")]).describe("Wallet address for automatic crypto withdrawal (fiat->crypto or crypto->crypto).\nOmit for conversion-only.").optional(), "external_account_id": z.union([z.string().describe("External account ID for automatic fiat withdrawal (crypto->fiat only).\nOmit for conversion-only."), z.null().describe("External account ID for automatic fiat withdrawal (crypto->fiat only).\nOmit for conversion-only.")]).describe("External account ID for automatic fiat withdrawal (crypto->fiat only).\nOmit for conversion-only.").optional() }).describe("Destination asset and optional withdrawal configuration.\n- For crypto withdrawal destination: `network` is required when `wallet_address` is provided\n- For fiat destination: `network` should be omitted\n- `wallet_address`: for fiat->crypto or crypto->crypto withdrawal to external wallet\n- `external_account_id`: for crypto->fiat withdrawal to bank account"), "idempotency_key": z.string() }).strict().describe("Request body for creating a new Auto-Conversion Rule.") }).strict().describe("Create Auto-Conversion Rule\n\nCreate an Auto-Conversion Rule for fiat->crypto, crypto->fiat, or crypto->crypto conversions.\n\n**Supported Assets:**\n- `USD`, `USDC`, `USDT`, `PYUSD`, `RLUSD`, `USDG`, `USDP`, `EURC`, `MXNB`\n**Supported Networks:**\n- Fiat deposit networks: `US_FEDWIRE`, `SWIFT`\n- Crypto networks: `ETHEREUM`, `POLYGON`, `BASE`, `ARBITRUM`, `AVALANCHE`, `BNBCHAIN`, `SOLANA`, `TRON`\n\n**Validation Rules:**\n- Supported pairs: fiat->crypto, crypto->fiat, and crypto->crypto; fiat->fiat is NOT supported\n- `Idempotency-Key` header is required and must be a valid UUID v4\n- Source network must match asset type (fiat asset requires fiat network, crypto asset requires crypto network)\n- For crypto withdrawal destination: `network` is required when `wallet_address` is provided\n- For fiat destination: `network` will be omitted\n\n**Withdrawal Configuration:**\n- Fiat-to-Crypto or Crypto->Crypto with withdrawal: provide `wallet_address` (external crypto wallet address)\n- Crypto-to-Fiat with withdrawal: provide `external_account_id` (bank account ID from external-accounts API)\n- Conversion-only (no withdrawal): omit both fields, converted funds remain in customer's account\n\n**Idempotency & Webhook Behavior:**\n- This endpoint creates resources asynchronously. The webhook notification may arrive **before** the HTTP response returns.\n- Use the `Idempotency-Key` to query the resource status via webhook response, enabling proper idempotency control.\n- **Recommended flow:** Instead of waiting for the HTTP response and then the webhook, clients can use the webhook arrival as the completion signal and query by `Idempotency-Key` to verify the result.\n- This approach prevents \"dangling wait\" scenarios where clients unnecessarily wait for the HTTP response when the webhook has already confirmed the outcome.\n\n**Response & Status:**\n- The response will have `status=PENDING` and `source_deposit_info=null` because deposit info is being prepared asynchronously.\n- Once deposit info is ready, the status will transition to `ACTIVE` and `source_deposit_info` will contain bank deposit details or crypto wallet address.\n- Use the retrieve endpoint or webhook to get the full details when the rule becomes `ACTIVE`.")
toolSchemas["auto_conversion_rules.create"] = AutoConversionRulesCreateSchema;

const AutoConversionRulesListSchema = z.object({ "customer_id": z.string().describe("Customer ID (UUID format)"), "params": z.object({ "include_subaccounts": z.boolean().describe("For main accounts, include rules from the main account and all sub-accounts (default: false).\nSub-accounts are always scoped to themselves.").optional(), "page": z.number().int().gte(1).describe("Page number (starts from 1, default: 1)").optional(), "size": z.number().int().gte(1).lte(100).describe("Number of items per page (1-100, default: 10)").optional() }).strict().optional() }).strict().describe("List Auto-Conversion Rules\n\nRetrieve all Auto-Conversion Rules for a customer with pagination support.\n\n**Note:** List response does not include `source_deposit_info`. Use the retrieve endpoint to get full details including deposit info.\n\n**Sub-accounts**\nSet `include_subaccounts=true` on the main account to list Auto-Conversion Rules across the main account and all sub-accounts under the same enterprise. Sub-account requests are always scoped to that sub-account. Each item carries its owning `customer_id` and `account_id`. Defaults to `false` (current customer only).\n\n**Pagination**\nTwo query parameter formats are supported:\n- Flat format (recommended): `?page=1&size=10`\n- Nested format: `?pagination=page=1&size=10`")
toolSchemas["auto_conversion_rules.list"] = AutoConversionRulesListSchema;

const AutoConversionRulesGetSchema = z.object({ "customer_id": z.string().describe("Customer ID (UUID format)"), "auto_conversion_rule_id": z.string().describe("Auto-Conversion Rule ID (UUID format)") }).strict().describe("Get Auto-Conversion Rule\n\nRetrieve detailed Auto-Conversion Rule information.\n\n**Status & Deposit Info:**\n- `PENDING`: Deposit info is being prepared. `source_deposit_info` will be `null`.\n- `ACTIVE`: Deposit info is ready. `source_deposit_info` contains bank Wire/SWIFT details for fiat source, or wallet address for crypto source.\n\n**Deposit Info:** Use the `source_deposit_info` to fund the Auto-Conversion Rule once the status is `ACTIVE`.")
toolSchemas["auto_conversion_rules.get"] = AutoConversionRulesGetSchema;

const AutoConversionRulesDeleteSchema = z.object({ "customer_id": z.string().describe("Customer ID (UUID format)"), "auto_conversion_rule_id": z.string().describe("Auto-Conversion Rule ID (UUID format)") }).strict().describe("Delete Auto-Conversion Rule\n\nDelete an Auto-Conversion Rule.\n\n**Note:** Cannot delete if there are pending orders associated with the Auto-Conversion Rule. Wait for all orders to complete or fail before deleting.")
